---
import { Label } from "@/components/ui/label"
import { Slider } from "@/components/ui/slider"

const value = [0.3, 0.7]
---

<div class="mx-auto grid w-full max-w-xs gap-3" data-slider-controlled>
  <div class="flex items-center justify-between gap-2">
    <Label data-slider-label>Temperature</Label>
    <span class="text-sm text-muted-foreground" data-slider-value>
      {value.join(", ")}
    </span>
  </div>
  <Slider defaultValue={[value[0], value[1]]} min={0} max={1} step={0.1} />
</div>

<script>
  const initialize = () => {
    for (const root of document.querySelectorAll("[data-slider-controlled]")) {
      if (root.hasAttribute("data-bound")) continue
      root.setAttribute("data-bound", "")
      // Name each thumb after the visible label: the thumbs are the
      // focusable sliders, not the root.
      const name = root
        .querySelector("[data-slider-label]")
        ?.textContent?.trim()
      const thumbs = root.querySelectorAll('[data-slot="slider-thumb"]')
      thumbs.forEach((thumb, index) =>
        thumb.setAttribute(
          "aria-label",
          thumbs.length > 1
            ? `${name} ${index === 0 ? "minimum" : "maximum"}`
            : `${name}`
        )
      )
      const output = root.querySelector("[data-slider-value]")
      root
        .querySelector('[data-slot="slider"]')
        ?.addEventListener("slider:change", (event) => {
          const { value } = (event as CustomEvent<{ value: number | number[] }>)
            .detail
          if (output) output.textContent = [value].flat().join(", ")
        })
    }
  }

  initialize()
  document.addEventListener("astro:page-load", initialize)
</script>

